22	 * Accepts the legacy `probability` field for backwards compatibility and maps it to `threshold`.
23	 */
24	export function normalizeSafetySettings(
25	  safetySettings: CompletionOptions['safetySettings'],
26	): { category: string; threshold: string }[] | undefined {
27	  if (!safetySettings) {
28	    return undefined;
29	  }
